INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1018, '数学', '三年级', '应用题', 2, '{"stem": "人体中含有大量水分，平均每千克体重含水700克。小明的体重是42千克，他体内大约含水多少克？", "options": null}', '29400克', '求42个700克是多少，用乘法：700×42。先算42×7=294，700末尾有两个0，在294后面添两个0，得29400。答：小明体内大约含水29400克。', 'paper', '["practice", "ykl3sx", "4.5"]', '["paper_png/ykl3_sx/p077.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1034, '数学', '三年级', '应用题', 2, '{"stem": "某体育用品商店6个乒乓球装一盒卖30元。照这样计算，买12个乒乓球需要多少元？90元可以买多少个这样的乒乓球？", "options": null}', '60元；18个', '12÷6=2（盒），30×2=60（元），买12个需要60元；90÷30=3（盒），6×3=18（个），90元可以买18个乒乓球。', 'paper', '["practice", "ykl3sx", "4.5"]', '["paper_png/ykl3_sx/p077.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1027, '数学', '三年级', '填空', 2, '{"stem": "用3、4、7、31四个数写出有余数的除法算式。能写几个就写几个。", "options": null}', '31÷4=7……3，31÷7=4……3', '有余数的除法中，余数必须比除数小。31÷4：4×7=28，31-28=3，余数3比4小；31÷7：7×4=28，31-28=3，余数3比7小。用3、4、7、31四个数，每个算式都要用上这四个数，只能写出这两个算式。', 'paper', '["practice", "ykl3sx", "4.5"]', '["paper_png/ykl3_sx/p077.png"]', 0);
